const http = require('http');

const baseUrl = 'http://localhost:3001/mcp/list_files';
const projectRoot = $vars.projectRoot || '.';
const authToken = $vars.authToken || '';

// Кодируем заголовок для поддержки кириллицы и спецсимволов
const encodedProjectRoot = encodeURIComponent(projectRoot);

const body = JSON.stringify({
  parameters: {
    path: '.',
    recursive: false
  }
});

return new Promise((resolve) => {
  const req = http.request(baseUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
      'Authorization': 'Bearer ' + authToken,
      'X-Project-Root': encodedProjectRoot
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      if (res.statusCode !== 200) {
        resolve('Error: ' + res.statusCode + ' - ' + data.slice(0, 300));
      } else {
        try {
          const json = JSON.parse(data);
          if (json.success && json.data?.files) {
            const fileList = json.data.files.map(f => f.path + ' (' + f.type + ')').join('\n');
            resolve('Files in project:\n' + fileList);
          } else {
            resolve(data);
          }
        } catch (e) {
          resolve(data);
        }
      }
    });
  });

  req.on('error', (err) => resolve('Error: ' + err.message));
  req.write(body);
  req.end();
});
